/bin/bash -lc "node --input-type=module <<'EOF'
import { chromium } from '/tmp/storyfolio-sheet-cli-Ipz2Lh/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({executablePath:'/tmp/storyfolio-browser-cache/chromium-1248/chrome-linux64/chrome',headless:true,args:['--no-sandbox']});
const page = await browser.newPage();
await page.goto('file://' + process.cwd() + '/checks/setup/index.html');
console.log({title:await page.title(),heading:await page.locator('h1').innerText(),body:await page.locator('body').innerText()});
await page.screenshot({path:'checks/setup/browser.png'});
await browser.close();
EOF"

